def transform(grid):
    # Superimpose the four 3x6 layers using the demonstrated color priority:
    # 5 > 4 > 8 > 2 > 0.
    h, w = len(grid), len(grid[0])
    layers = [grid[i:i + h // 4] for i in range(0, h, h // 4)]
    priority = {5: 0, 4: 1, 8: 2, 2: 3, 0: 4}
    return [[min((layer[r][c] for layer in layers), key=priority.__getitem__)
             for c in range(w)] for r in range(h // 4)]
